const Component = ({ item }) => {
  const frame = useCurrentFrame();
  const p = item.props;
  const rootStyle = {position:'absolute',inset:0,backgroundColor:'transparent',display:'flex',alignItems:'center',padding:12};
  const fontSize = Math.min(164,1120/Math.max(7,p.text.length));
  const rowStyle = {display:'flex',alignItems:'baseline',color:p.ink,fontFamily:p.font,fontSize:fontSize,fontWeight:900,lineHeight:1.15,letterSpacing:-4,whiteSpace:'nowrap'};
  const chars = p.text.split('');
  const letters = chars.map((char,index)=>{
    const start = 44 + index*5;
    const alpha = interpolate(frame,[start,start+9],[0,1],{extrapolateLeft:'clamp',extrapolateRight:'clamp'});
    const lift = interpolate(frame,[start,start+6,start+12],[20,-4,0],{extrapolateLeft:'clamp',extrapolateRight:'clamp'});
    const style = {display:'inline-block',opacity:alpha,transform:'translateY('+lift+'px)'};
    return <span key={index} style={style}>{char}</span>;
  });
  return <div style={rootStyle}><div style={rowStyle}>{letters}</div></div>;
};

